1. import { Layerr } from "layerr";
2. import Stream from "stream";
3. import { fromBase64 } from "../tools/encode.js";
4. import { joinURL } from "../tools/url.js";
5. import { encodePath } from "../tools/path.js";
6. import { calculateDataLength } from "../tools/size.js";
7. import { isWeb } from "../compat/env.js";
8. import { request, prepareRequestOptions } from "../request.js";
9. import { handleResponseCode } from "../response.js";
10. import { AuthType, ErrorCode } from "../types.js";
11. export async function putFileContents(context, filePath, data, options = {}) {
12.     const { contentLength = true, overwrite = true } = options;
13.     const headers = {
14.         "Content-Type": "application/octet-stream"
15.     };
16.     if (!isWeb() &&
17.         typeof Stream !== "undefined" &&
18.         typeof Stream?.Readable !== "undefined" &&
19.         data instanceof Stream.Readable) {
20.         // Skip, no content-length
21.     }
22.     else if (contentLength === false) {
23.         // Skip, disabled
24.     }
25.     else if (typeof contentLength === "number") {
26.         headers["Content-Length"] = `${contentLength}`;
27.     }
28.     else {
29.         headers["Content-Length"] = `${calculateDataLength(data)}`;
30.     }
31.     if (!overwrite) {
32.         headers["If-None-Match"] = "*";
33.     }
34.     const requestOptions = prepareRequestOptions({
35.         url: joinURL(context.remoteURL, encodePath(filePath)),
36.         method: "PUT",
37.         headers,
38.         data
39.     }, context, options);
40.     const response = await request(requestOptions);
41.     try {
42.         handleResponseCode(context, response);
43.     }
44.     catch (err) {
45.         const error = err;
46.         if (error.status === 412 && !overwrite) {
47.             return false;
48.         }
49.         else {
50.             throw error;
51.         }
52.     }
53.     return true;
54. }
55. export function getFileUploadLink(context, filePath) {
56.     let url = `${joinURL(context.remoteURL, encodePath(filePath))}?Content-Type=application/octet-stream`;
57.     const protocol = /^https:/i.test(url) ? "https" : "http";
58.     switch (context.authType) {
59.         case AuthType.None:
60.             // Do nothing
61.             break;
62.         case AuthType.Password: {
63.             const authPart = context.headers.Authorization.replace(/^Basic /i, "").trim();
64.             const authContents = fromBase64(authPart);
65.             url = url.replace(/^https?:\/\//, `${protocol}://${authContents}@`);
66.             break;
67.         }
68.         default:
69.             throw new Layerr({
70.                 info: {
71.                     code: ErrorCode.LinkUnsupportedAuthType
72.                 }
73.             }, `Unsupported auth type for file link: ${context.authType}`);
74.     }
75.     return url;
76. }
